CREATE COLUMN TABLE "TEST_AP"."CDPM" ("PermId" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(64), "ObjectType" INTEGER CS_INT, "ObjectKey" NVARCHAR(200), "Father" INTEGER CS_INT, "PermOption" SMALLINT CS_INT DEFAULT 0, "System" NVARCHAR(1) DEFAULT 'N', "Hidden" NVARCHAR(1) DEFAULT 'N', "SortOrder" INTEGER CS_INT, PRIMARY KEY ("PermId")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."CDPM" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$ObjectType$Name$','ObjectType','Name'));
CREATE INDEX "CDPM_OBJECT" ON "TEST_AP"."CDPM" ( "ObjectType" ASC, "Name" ASC )